import { test, expect } from '@playwright/test';
import { ADMIN_STATE, UNIT_PLACEHOLDER, openNewJobAddressDetails, setEnglish, unitInput } from './address-helpers';

test.use({ storageState: ADMIN_STATE });

test.describe('Unit/Apt: placeholder формата (#8ffd6e26)', () => {
  test.beforeEach(async ({ page }) => { await setEnglish(page); });

  test('New Job: Unit/Apt shows the placeholder "Apt 5B / Unit 12" #8ffd6e26 @desktop @prod-safe', async ({ page }) => {
    await openNewJobAddressDetails(page);
    await expect(unitInput(page)).toHaveAttribute('placeholder', UNIT_PLACEHOLDER);
  });

  test('New Client: Unit/Apt shows the placeholder "Apt 5B / Unit 12" #8ffd6e26 @desktop @prod-safe', async ({ page }) => {
    await page.goto('/CustomerForm?action=new');
    await expect(unitInput(page)).toBeVisible();
    await expect(unitInput(page)).toHaveAttribute('placeholder', UNIT_PLACEHOLDER);
  });

  test('New Lead: Unit/Apt shows the placeholder "Apt 5B / Unit 12" #8ffd6e26 @desktop @prod-safe', async ({ page }) => {
    await page.goto('/CreateLead');
    await expect(unitInput(page)).toBeVisible();
    await expect(unitInput(page)).toHaveAttribute('placeholder', UNIT_PLACEHOLDER);
  });
});
